"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["5659"],{81819(e){e.exports=JSON.parse('{"id":"FIN-470","slug":"customer-lifetime-value","term":"Customer Lifetime Value","also_known_as":[],"difficulty":"Intermediate","definition":"Customer lifetime value is the total profit a business expects to earn from a customer over the entire period of their relationship.","explanation":["Customer lifetime value, often shortened to CLV or LTV, helps businesses understand how much each customer is worth over time, not just from a single purchase.","A simple estimate multiplies the average profit per customer per period by the expected number of periods the customer stays. For example, if a subscription service earns 10 of profit per customer each month and the average customer stays for 24 months, the customer lifetime value is about 240. More detailed calculations also account for the time value of money and changes in spending over time.","Customer lifetime value is most useful when compared with customer acquisition cost, the amount spent to win a new customer. If it costs 80 to acquire a customer worth 240, the business is creating value. If it costs 300, it is losing money on each new customer.","Businesses use CLV to decide how much to spend on marketing, which customers to focus on and how much to invest in keeping customers happy. Increasing how long customers stay, through better service or loyalty programmes, can raise lifetime value significantly."],"note":"","total":1725,"prev":{"slug":"customer-due-diligence","term":"Customer Due Diligence (CDD)"},"next":{"slug":"customer-retention","term":"Customer Retention"}}')}}]);